insert into sys_cloud_push_job (
    job_id, project_id, pull_key, state, percent, phase, error_message, message,
    session_id, selection_json, logs_json, packed_bytes, max_total_bytes, legacy_full,
    create_time, update_time
) values (
    #{jobId}, #{projectId}, #{pullKey}, #{state}, #{percent}, #{phase}, #{errorMessage}, #{message},
    #{sessionId}, #{selectionJson}, #{logsJson}, #{packedBytes}, #{maxTotalBytes}, #{legacyFull},
    #{createTime}, #{updateTime}
)

insert into sys_cloud_push_part (
    job_id, part_id, part_type, ref_key, state, expected_bytes, actual_bytes, sha256,
    temp_path, attempt_count, error_message, sort_order, update_time
) values (
    #{jobId}, #{partId}, #{partType}, #{refKey}, #{state}, #{expectedBytes}, #{actualBytes}, #{sha256},
    #{tempPath}, #{attemptCount}, #{errorMessage}, #{sortOrder}, #{updateTime}
)
